    isOpenForRegistration: true,
    registrationLink: "https://sma.unicartagena.edu.co:8443/Smaix20/vista/admisiones/convocatorias/formCalls.jsp#POS",
    officialLink: "https://unicartagena.edu.co/posgrados",
    creditos: "44",
    mallaUrl: "https://drive.google.com/file/d/1ZEIhdmM_lA7keT8dA2_p74L0gcG3jdZG/view?usp=sharing",
    smaLink: "https://sma.unicartagena.edu.co:8443/Smaix20/vista/admisiones/convocatorias/formCalls.jsp#POS",
    resolucionMen: "Res. 9030 de 28 de Agosto de 2019 del MEN",
    vigencia: "7 años",
