    creditos: "262",
    mallaUrl: "https://drive.google.com/file/d/1mrH1AfMBZpiePNPRbx_Zl2Q8mV3DWPk9/view?usp=sharing",
    smaLink: "https://sma.unicartagena.edu.co:8443/Smaix20/vista/admisiones/convocatorias/formCalls.jsp#POS",
    resolucionMen: "Res. 21976 de 18 de Noviembre de 2021 del MEN",
